ALTER TABLE "User" ADD COLUMN "dashboardDepartment" JSONB;
ALTER TABLE "MaintenancePlan" ADD COLUMN kind TEXT NOT NULL DEFAULT 'pm' CHECK (kind IN ('pm','cil'));
CREATE TABLE "FiveSPlan" (id TEXT PRIMARY KEY,"locationId" TEXT NOT NULL REFERENCES "Location"(id),title TEXT NOT NULL,questions JSONB NOT NULL,"assigneeIds" JSONB NOT NULL,active BOOLEAN NOT NULL DEFAULT true,version INTEGER NOT NULL DEFAULT 1,"createdBy" TEXT NOT NULL REFERENCES "User"(id),history JSONB NOT NULL);
CREATE TABLE "FiveSAudit" (id TEXT PRIMARY KEY,"planId" TEXT NOT NULL REFERENCES "FiveSPlan"(id),"locationId" TEXT NOT NULL REFERENCES "Location"(id),"userId" TEXT NOT NULL REFERENCES "User"(id),snapshot JSONB NOT NULL,responses JSONB NOT NULL,media JSONB NOT NULL,score INTEGER NOT NULL,maximum INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "FiveSAudit_locationId_createdAt_idx" ON "FiveSAudit" ("locationId","createdAt");
CREATE TABLE "Defect" (id TEXT PRIMARY KEY,"equipmentId" TEXT NOT NULL REFERENCES "Equipment"(id),title TEXT NOT NULL,description TEXT NOT NULL,priority TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Open',"reportedBy" TEXT NOT NULL REFERENCES "User"(id),"assigneeId" TEXT REFERENCES "User"(id),media JSONB NOT NULL,"equipmentSnapshot" JSONB NOT NULL,version INTEGER NOT NULL DEFAULT 1,history JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"maintainxStatus" TEXT NOT NULL DEFAULT 'Not submitted',"maintainxId" TEXT,"submissionAt" TIMESTAMP(3),"submissionError" TEXT);
CREATE INDEX "Defect_equipmentId_status_idx" ON "Defect" ("equipmentId",status);
CREATE TABLE "RegistrationRequest" (id TEXT PRIMARY KEY,username TEXT NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL,department TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Pending',"reviewedBy" TEXT REFERENCES "User"(id),"createdUserId" TEXT REFERENCES "User"(id),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"reviewedAt" TIMESTAMP(3));
CREATE INDEX "RegistrationRequest_status_createdAt_idx" ON "RegistrationRequest" (status,"createdAt");
CREATE UNIQUE INDEX "RegistrationRequest_pending_username" ON "RegistrationRequest" (username) WHERE status='Pending';
CREATE TABLE "PasswordReset" ("tokenHash" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"(id),"userVersion" INTEGER NOT NULL,expires TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
UPDATE "Policy" SET grants=grants || '["fiveS","defects"]'::jsonb WHERE role IN ('Manager','DL/TL','Operator');
